(ns diplomat.general-category
  "GENERATED by jolt-diplomat-backend.")

(def kw->int {
  :unassigned 0
  :uppercase-letter 1
  :lowercase-letter 2
  :titlecase-letter 3
  :modifier-letter 4
  :other-letter 5
  :nonspacing-mark 6
  :enclosing-mark 7
  :spacing-mark 8
  :decimal-number 9
  :letter-number 10
  :other-number 11
  :space-separator 12
  :line-separator 13
  :paragraph-separator 14
  :control 15
  :format 16
  :private-use 17
  :surrogate 18
  :dash-punctuation 19
  :open-punctuation 20
  :close-punctuation 21
  :connector-punctuation 22
  :other-punctuation 23
  :math-symbol 24
  :currency-symbol 25
  :modifier-symbol 26
  :other-symbol 27
  :initial-punctuation 28
  :final-punctuation 29
  })

(def int->kw (clojure.set/map-invert kw->int))
